ee:variables.ee:set-variable:
output application/json
					var status = attributes.queryParams.*filterByStatus map "$" joinBy ","
					var policy = attributes.queryParams.*filterByPolicy map "$" joinBy ","
					var sortby = (attributes.queryParams.*sortBy)
					var sorttype = attributes.queryParams.sortType
					var sort = sortby map ((item, index) -> item ++ " " ++ ( sorttype default "ASC" ))
					---
					{
						sortBy: (sort joinBy ','),
						filterByStatus: if ( !isEmpty(attributes.queryParams.filterByStatus) ) status else null,
						filterByPolicy: if ( !isEmpty(attributes.queryParams.filterByPolicy) ) policy else null,
						searchBy: attributes.queryParams.searchBy}

ee:message.ee:set-payload:
%dw 2.0
					output application/java
					var users = p('db.query.delete.users')  replace ':userName' with("'" ++ vars.userId ++ "'")
					var userRegInfo = p('db.query.delete.usersRegInfo')  replace ':userName' with("'" ++ vars.userId ++ "'")
					var userRoles = p('db.query.delete.userRoles') replace ':userName' with("'" ++ vars.userId ++ "'")
					---
					userRoles ++ ';' ++ userRegInfo ++ ';' ++ users

ee:variables.ee:set-variable:
%dw 2.0
					output application/java
					---
					{
						tvpName: "SITE_DETAILS_TYPE"
					} as Object {
						class: "com.microsoft.sqlserver.jdbc.SQLServerDataTable"
					}

output application/java
var query = p('db.query.select.vrmOrgId')
var vrm =  "'" ++ (payload.vrmManagementRequest.vrm) ++ "'" replace ',' with("','")
---
query replace ':vrm' with(vrm)

%dw 2.0
							output application/java
							var userQuery = p('db.query.update.adminUserDetails')
							var userSiteMapQuery = p('db.query.update.userSiteMapDetails')
							var siteDetailQuery = p('db.query.update.siteDetails')
							---
							payload

ee:message.ee:set-payload:
%dw 2.0
								output application/json
								---
								{
									oktaAccountRequest: {
										firstName: payload.FIRST_NAME,
										lastName: payload.SURNAME default payload.FIRST_NAME,
										email: payload.USER_NAME,
										(phoneNumber: payload.CONTACT_TEL) if (!isBlank(payload.CONTACT_TEL))
									}
								}

%dw 2.0
								output application/java
								---
								{
									USER_ID : vars.dbRequest.USER_ID
								}
